// データ正規化と重複除去
const items = $input.all();
const normalizedItems = [];
const seenTitles = new Set();

for (const item of items) {
  let data = item.json;
  let normalized = {};

  // ソース別データ正規化
  if (data.title && data.link) {
    // RSS形式 (OpenAI)
    normalized = {
      title: data.title,
      url: data.link,
      description: data.description || '',
      publishedDate: data.pubDate || data.isoDate,
      source: 'OpenAI Blog',
      sourceWeight: 2.0
    };
  } else if (data.data && Array.isArray(data.data.children)) {
    // Reddit形式
    for (const post of data.data.children) {
      const postData = post.data;
      if (postData.title && postData.url) {
        normalized = {
          title: postData.title,
          url: postData.url,
          description: postData.selftext || '',
          publishedDate: new Date(postData.created_utc * 1000).toISOString(),
          source: 'Reddit ML',
          sourceWeight: 1.5,
          score: postData.score
        };

        // タイトル類似度チェック (85%以上で重複とみなす)
        const titleLower = normalized.title.toLowerCase();
        let isDuplicate = false;

        for (const seenTitle of seenTitles) {
          const similarity = calculateSimilarity(titleLower, seenTitle);
          if (similarity >= 0.85) {
            isDuplicate = true;
            break;
          }
        }

        if (!isDuplicate) {
          seenTitles.add(titleLower);
          normalizedItems.push({ json: normalized });
        }
      }
    }
    continue;
  } else if (Array.isArray(data)) {
    // Dev.to形式
    for (const article of data) {
      if (article.title && article.url) {
        normalized = {
          title: article.title,
          url: article.url,
          description: article.description || '',
          publishedDate: article.published_at,
          source: 'Dev.to',
          sourceWeight: 1.3,
          tags: article.tag_list
        };

        // 重複チェック
        const titleLower = normalized.title.toLowerCase();
        let isDuplicate = false;

        for (const seenTitle of seenTitles) {
          const similarity = calculateSimilarity(titleLower, seenTitle);
          if (similarity >= 0.85) {
            isDuplicate = true;
            break;
          }
        }

        if (!isDuplicate) {
          seenTitles.add(titleLower);
          normalizedItems.push({ json: normalized });
        }
      }
    }
    continue;
  } else if (typeof data === 'string' && data.includes('<?xml')) {
    // ArXiv XML形式の処理は簡略化
    continue;
  }

  // 通常の単一アイテム処理
  if (normalized.title) {
    const titleLower = normalized.title.toLowerCase();
    let isDuplicate = false;

    for (const seenTitle of seenTitles) {
      const similarity = calculateSimilarity(titleLower, seenTitle);
      if (similarity >= 0.85) {
        isDuplicate = true;
        break;
      }
    }

    if (!isDuplicate) {
      seenTitles.add(titleLower);
      normalizedItems.push({ json: normalized });
    }
  }
}

// タイトル類似度計算関数
function calculateSimilarity(str1, str2) {
  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;

  if (longer.length === 0) return 1.0;

  const distance = levenshteinDistance(longer, shorter);
  return (longer.length - distance) / longer.length;
}

function levenshteinDistance(str1, str2) {
  const matrix = [];

  for (let i = 0; i <= str2.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= str1.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= str2.length; i++) {
    for (let j = 1; j <= str1.length; j++) {
      if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }

  return matrix[str2.length][str1.length];
}

return normalizedItems;

