// 重要度スコアリングと分析結果統合
const items = $input.all();
const processedItems = [];

for (const item of items) {
  const data = item.json;
  let aiAnalysis = {};

  // AI分析結果の解析
  try {
    if (data.response && typeof data.response === 'string') {
      aiAnalysis = JSON.parse(data.response);
    } else if (data.summary) {
      aiAnalysis = data;
    }
  } catch (e) {
    // AI分析が失敗した場合のフォールバック
    aiAnalysis = {
      summary: data.description?.substring(0, 150) + '...' || 'No summary available',
      category: 'Technical',
      importance_score: 5.0,
      keywords: [],
      sentiment: 'neutral'
    };
  }

  // 重要度スコア計算
  let finalScore = parseFloat(aiAnalysis.importance_score) || 5.0;

  // ソース別重み付け
  const sourceWeight = data.sourceWeight || 1.0;
  finalScore *= sourceWeight;

  // キーワードベース加点
  const highValueKeywords = ['gpt', 'chatgpt', 'claude', 'breakthrough', 'research', 'breakthrough', 'innovation'];
  const titleLower = data.title?.toLowerCase() || '';
  const descLower = data.description?.toLowerCase() || '';

  for (const keyword of highValueKeywords) {
    if (titleLower.includes(keyword) || descLower.includes(keyword)) {
      finalScore += 0.5;
    }
  }

  // 新しさによる調整 (24時間以内+1.0点)
  if (data.publishedDate) {
    const publishDate = new Date(data.publishedDate);
    const now = new Date();
    const hoursDiff = (now - publishDate) / (1000 * 60 * 60);

    if (hoursDiff <= 24) {
      finalScore += 1.0;
    } else if (hoursDiff <= 72) {
      finalScore += 0.5;
    }
  }

  // 最大10点に正規化
  finalScore = Math.min(finalScore, 10.0);

  const processedItem = {
    ...data,
    summary: aiAnalysis.summary,
    category: aiAnalysis.category,
    importance_score: finalScore,
    keywords: aiAnalysis.keywords || [],
    sentiment: aiAnalysis.sentiment,
    processed_at: new Date().toISOString()
  };

  processedItems.push({ json: processedItem });
}

// 重要度順でソート
processedItems.sort((a, b) => b.json.importance_score - a.json.importance_score);

return processedItems;

